/bin/bash -lc "python - <<'PY'
import json
from pathlib import Path
old = '''function parseLine(line) {
  return line.split(\",\");
}'''
new = '''function parseLine(line) {
  const cells = [];
  let cell = \"\";
  let quoted = false;
  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    if (char === '\"') {
      if (quoted && line[i + 1] === '\"') {
        cell += '\"';
        i++;
      } else {
        quoted = "'!quoted;
      }
    } else if (char === "," && !quoted) {
      cells.push(cell);
      cell = "";
    } else {
      cell += char;
    }
  }
  cells.push(cell);
  return cells;
}'"'''
assert Path('broken.js').read_text().count(old) == 1
Path('answer.txt').write_text('"'```json'"\\n' + json.dumps([{'old': old, 'new': new}], indent=2) + '\\n"'```'"\\n')
PY"

